Convex 1.44.0. The schema declares `documents.authorId: v.id("users")` and `.index("by_author", ["authorId"])`. One user has two documents. There are no concurrent writes. This mutation runs with that user ID:

```ts
import { mutation } from "./_generated/server";
import { v } from "convex/values";

export const removeUser = mutation({
  args: { userId: v.id("users") },
  handler: async (ctx, args) => {
    await ctx.db.delete("users", args.userId);
    return null;
  },
});
```
